#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/ANDROID_STYLE_UI.md ]] || { echo 'Run from the repository root after the native Android-style UI update.' >&2; exit 1; }
python3 - <<'WINDOWS_FEATURES'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/desktop_store.dart': '',
'desktop/hyper_player/test/desktop_store_test.dart': '',
'desktop/hyper_player/FEATURE_PARITY.md': '',
}
for name, value in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(value))
print('Cumulative Windows playback tools and collections update applied. Android unchanged.')
WINDOWS_FEATURES
